import{_ as e,o,a,b as d}from"./app.C41L12d5.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"附录","link":"/guide/programming_guide/appendix/show_kernel_debug_data_tool"},{"text":"optype_collector工具","link":"/guide/programming_guide/appendix/optype_collector_tool"}]},"headers":[],"relativePath":"guide/programming_guide/appendix/optype_collector_tool.md","filePath":"guide/programming_guide/appendix/optype_collector_tool.md","outlineHeaders":[{"level":2,"title":"工具安装","slug":"工具安装","link":"#工具安装"},{"level":2,"title":"命令格式","slug":"命令格式","link":"#命令格式"},{"level":2,"title":"返回值","slug":"返回值","link":"#返回值"},{"level":2,"title":"输出说明","slug":"输出说明","link":"#输出说明"},{"level":2,"title":"使用样例","slug":"使用样例","link":"#使用样例"}],"lastUpdated":1788515292000}'),c={name:"guide/programming_guide/appendix/optype_collector_tool.md"};function s(p,t,l,i,n,h){return o(),a("div",null,[...t[0]||(t[0]=[d(`<div><article class="markdown-body"><h1>optype_collector工具<span id="ZH-CN_TOPIC_OPTYPE_COLLECTOR"></span></h1><p>optype_collector工具用于采集内置/自定义算子包中指定AI处理器的OpType信息，并检测自定义算子包与内置算子包、自定义算子包之间的OpType重名问题，帮助开发者在自定义算子安装或交付前提前发现命名冲突。</p><p>工具支持扫描以下信息来源：</p><ul><li><code>CANN</code>安装目录下的CANN内置算子包。</li><li><code>CANN</code>安装目录下的自定义算子包。</li><li><code>ASCEND_CUSTOM_OPP_PATH</code>指定的一个或多个自定义算子包路径。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>OpType表示算子类型名称，是算子原型、算子实现和算子包管理中的关键标识。自定义算子OpType应避免与内置算子或其他自定义算子重复。</li><li>冲突检测模式会覆盖如下两类场景： <ul><li>自定义算子包与CANN内置算子包之间的OpType重名。</li><li>不同自定义算子包之间的OpType重名。</li></ul></li></ul></div><h2 id="工具安装">工具安装<span id="section_optype_collector_install"></span><a class="header-anchor" href="#工具安装">​</a></h2><ol><li><p>安装optype_collector工具。</p><p>工具跟随CANN软件包发布，参考<a href="../../getting_started/environment_setup.html">环境准备</a>完成CANN安装后，即可使用该工具。</p></li><li><p>设置环境变量。</p><ul><li><p>root用户安装Ascend-cann-toolkit包时</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>source /usr/local/Ascend/cann/set_env.sh
</code></pre></div></li><li><p>非root用户安装Ascend-cann-toolkit包时</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>source \${HOME}/Ascend/cann/set_env.sh
</code></pre></div></li></ul><p>多个自定义算子包路径使用系统路径分隔符分隔。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>export ASCEND_CUSTOM_OPP_PATH=/home/custom_opp
</code></pre></div></li><li><p>检查工具是否安装成功。</p><p>执行如下命令，若能正常显示帮助信息，则表示工具环境正常，功能可正常使用。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector -h
</code></pre></div></li></ol><h2 id="命令格式">命令格式<span id="section_optype_collector_command"></span><a class="header-anchor" href="#命令格式">​</a></h2><p>本文中的<code>{soc_version}</code>表示AI处理器的型号。</p><ul><li><p>配置说明如下：</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><div data-filter="910b,910,310p,310b"><ul><li><p>针对如下产品：在安装AI处理器的服务器执行<code>npu-smi info</code>命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。<br><br></p><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><div data-filter="310b"><p>Atlas 200I/500 A2 推理产品</p></div><div data-filter="310p"><p>Atlas 推理系列产品</p></div><div data-filter="910"><p>Atlas 训练系列产品<br><br></p></div></li></ul></div><div data-filter="A3"><ul><li>针对<term>Atlas A3 训练系列产品</term>/<term>Atlas A3 推理系列产品</term>，在安装AI处理器的服务器执行<code>npu-smi info -t board -i &lt;id&gt; -c &lt;chip_id&gt;</code>命令进行查询，获取Chip Name和NPU Name信息，实际配置值为<code>Chip Name_NPU Name</code>。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：<br><code>id</code>：设备id，通过<code>npu-smi info -l</code>命令查出的NPU ID即为设备id，命令中表示为<code>&lt;id&gt;</code>。<br><code>chip_id</code>：芯片id，通过<code>npu-smi info -m</code>命令查出的Chip ID即为芯片id，命令中表示为<code>&lt;chip_id&gt;</code>。<br><br></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行<code>npu-smi info -t board -i &lt;id&gt;</code>命令进行查询，获取Chip Name和NPU Name信息，实际配置值为<code>Chip Name_NPU Name</code>。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。<br>其中：<code>id</code>为设备id，通过<code>npu-smi info -l</code>命令查出的NPU ID即为设备id，命令中表示为<code>&lt;id&gt;</code>。</li></ul></div></div></li><li><p><strong>输出内置算子OpType清单的命令</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector {soc_version}
optype_collector {soc_version} --builtin
</code></pre></div><p><strong>表1</strong> 参数说明<span id="table_optype_collector_builtin_params"></span></p><table><thead><tr><th>参数（区分大小写）</th><th>可选/必选</th><th>说明</th></tr></thead><tbody><tr><td><code>{soc_version}</code></td><td>必选</td><td>指定待扫描的AI处理器型号，可填写CANN支持的产品AI处理器型号。</td></tr><tr><td><code>--builtin</code></td><td>可选</td><td>仅输出CANN内置算子包中的OpType清单。未指定清单模式时，默认使用该模式。</td></tr></tbody></table></li><li><p><strong>输出自定义算子OpType清单的命令</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector {soc_version} --custom
</code></pre></div><p><strong>表2</strong> 参数说明<span id="table_optype_collector_custom_params"></span></p><table><thead><tr><th>参数（区分大小写）</th><th>可选/必选</th><th>说明</th></tr></thead><tbody><tr><td><code>{soc_version}</code></td><td>必选</td><td>指定待扫描的AI处理器型号，可填写CANN支持的产品AI处理器型号。</td></tr><tr><td><code>--custom</code></td><td>必选</td><td>仅输出自定义算子包中的OpType清单。工具会扫描<code>CANN包安装目录</code>和<code>ASCEND_CUSTOM_OPP_PATH</code>指定路径下的自定义算子包。</td></tr></tbody></table></li><li><p><strong>输出内置算子与自定义算子OpType清单的命令</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector {soc_version} --all
</code></pre></div><p><strong>表3</strong> 参数说明<span id="table_optype_collector_all_params"></span></p><table><thead><tr><th>参数（区分大小写）</th><th>可选/必选</th><th>说明</th></tr></thead><tbody><tr><td><code>{soc_version}</code></td><td>必选</td><td>指定待扫描的AI处理器型号，可填写CANN支持的产品AI处理器型号。</td></tr><tr><td><code>--all</code></td><td>必选</td><td>同时输出CANN内置算子包和自定义算子包中的OpType清单。</td></tr></tbody></table></li><li><p><strong>检测OpType重名冲突的命令</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector --detect-conflicts {soc_version}
</code></pre></div><p><strong>表4</strong> 参数说明<span id="table_optype_collector_detect_params"></span></p><table><thead><tr><th>参数（区分大小写）</th><th>可选/必选</th><th>说明</th></tr></thead><tbody><tr><td><code>--detect-conflicts {soc_version}</code></td><td>必选</td><td>检测指定AI处理器版本下自定义算子OpType是否与CANN内置算子OpType或其他自定义算子OpType重名。<code>{soc_version}</code>表示待检测的AI处理器型号，可填写CANN支持的产品AI处理器型号。</td></tr></tbody></table></li></ul><h2 id="返回值">返回值<span id="section_optype_collector_return_code"></span><a class="header-anchor" href="#返回值">​</a></h2><p><span id="table_optype_collector_return_code"></span></p><table><thead><tr><th>返回值</th><th>说明</th></tr></thead><tbody><tr><td><code>0</code></td><td>执行成功，且冲突检测模式下未发现OpType重名冲突。</td></tr><tr><td><code>1</code></td><td>冲突检测模式下发现OpType重名冲突。</td></tr><tr><td><code>2</code></td><td>参数错误、环境变量缺失、目标AI处理器包不存在等阻塞类错误。</td></tr></tbody></table><h2 id="输出说明">输出说明<span id="section_optype_collector_output"></span><a class="header-anchor" href="#输出说明">​</a></h2><p>工具执行后会根据命令模式输出如下信息。</p><p><span id="table_optype_collector_output"></span></p><table><thead><tr><th>输出项</th><th>说明</th></tr></thead><tbody><tr><td><code>[Scan Info]</code></td><td>展示本次扫描的AI处理器版本、<code>ASCEND_HOME_PATH</code>和<code>ASCEND_CUSTOM_OPP_PATH</code>。</td></tr><tr><td><code>[Sources]</code></td><td>展示命中的信息来源，包括来源类型、状态、OpType数量、配置文件数量、输入AI处理器型号和扫描路径。</td></tr><tr><td><code>[OpType List]</code></td><td>清单模式下输出OpType统计信息和OpType列表。</td></tr><tr><td><code>[Conflict Summary]</code></td><td>冲突检测模式下输出内置算子OpType数量、自定义算子包数量和冲突分组数量。</td></tr><tr><td><code>[Conflict n]</code></td><td>冲突检测模式下输出第n组冲突的包信息、冲突数量和冲突OpType列表。</td></tr><tr><td><code>[Warnings]</code></td><td>输出非阻塞类告警信息，如未设置<code>ASCEND_CUSTOM_OPP_PATH</code>、JSON文件解析失败等。</td></tr><tr><td><code>[Errors]</code></td><td>输出阻塞类错误信息，如CANN包环境变量未设置、目标AI处理器包不存在等。</td></tr></tbody></table><h2 id="使用样例">使用样例<span id="section_optype_collector_examples"></span><a class="header-anchor" href="#使用样例">​</a></h2><p>以下样例以<code>{soc_version}</code>为例。执行命令前，请确保已完成CANN环境变量配置；如需扫描外部自定义算子包，请确保已正确设置<code>ASCEND_CUSTOM_OPP_PATH</code>。</p><ul><li><p><strong>查看内置算子OpType清单</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector {soc_version} --builtin
</code></pre></div><p>执行上述命令，终端打印内置算子OpType清单，屏显信息形如：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>[Scan Info]
  SoC                    : {soc_version}
  ASCEND_HOME_PATH       : /usr/local/Ascend/latest
  ASCEND_CUSTOM_OPP_PATH : /home/custom_opp

[Sources]
  Type     Status  OpTypes  ConfigFiles  SoC  Path
  -------  ------  -------  -----------  ----------  ---------------------------------------------------------------
  builtin  OK      3        1            {soc_version}  {op_soc_path}

[OpType List]
  SoC                    : {soc_version}
  Mode                   : builtin
  Total OpTypes          : 3

  OpType
  ------
  Add
  MatMul
  Relu
</code></pre></div></li><li><p><strong>查看自定义算子OpType清单</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector {soc_version} --custom
</code></pre></div><p>执行上述命令，终端打印自定义算子OpType清单。若命中多个自定义算子包，工具会按扫描来源分组展示，屏显信息形如：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>[Scan Info]
  SoC                    : {soc_version}
  ASCEND_HOME_PATH       : /usr/local/Ascend/latest
  ASCEND_CUSTOM_OPP_PATH : /home/custom_opp

[Sources]
  Type    Status  OpTypes  ConfigFiles  SoC  Path
  ------  ------  -------  -----------  ----------  ---------------------------------------------------------------
  custom  OK      2        1            {soc_version}  {op_soc_path1}
  custom  OK      2        1            {soc_version}  {op_soc_path2}

[OpType List]
  SoC                    : {soc_version}
  Mode                   : custom
  Total OpTypes          : 3

  [custom] {op_soc_path1}
  OpTypes          : 2
  SoC             : {soc_version}
    OpType
    ------
    Add
    CustomSame

  [custom] {op_soc_path2}
  OpTypes          : 2
  SoC             : {soc_version}
    OpType
    ------
    CustomSame
    OtherCustom
</code></pre></div></li><li><p><strong>查看全部OpType清单</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector {soc_version} --all
</code></pre></div><p>执行上述命令，终端同时打印内置算子包和自定义算子包中的OpType清单。该命令适用于排查某个OpType是否已经在当前CANN环境或自定义算子包中存在。</p></li><li><p><strong>检测OpType重名冲突</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>optype_collector --detect-conflicts {soc_version}
</code></pre></div><p>执行上述命令，工具会检测自定义算子OpType与内置算子OpType、自定义算子OpType之间是否重名。若发现冲突，返回值为<code>1</code>，屏显信息形如：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>[Conflict Summary]
  SoC                    : {soc_version}
  Built-in OpTypes       : 3
  Custom packages        : 2
  Custom vs Built-in     : 1 group(s)
  Custom vs Custom       : 1 group(s)

[Conflict 1] Custom package conflicts with built-in OpTypes
  Pkg  Type     Vendor    Path
  ---  -------  --------  ---------------------------------------------------------------
  A    custom   vendor_a  {op_soc_path1}
  B    builtin  -         {op_soc_path2}
  Conflict count         : 1
  Conflict OpTypes:
    - Add

[Conflict 2] Custom package conflicts with another custom package
  Pkg  Type    Vendor    Path
  ---  ------  --------  ---------------------------------------------------------------
  A    custom  vendor_a  {op_soc_path1}
  B    custom  vendor_b  {op_soc_path3}
  Conflict count         : 1
  Conflict OpTypes:
    - CustomSame
</code></pre></div><p>若未发现冲突，返回值为<code>0</code>，屏显信息形如：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>[Conflict Summary]
  SoC                    : {soc_version}
  Built-in OpTypes       : 3
  Custom packages        : 1
  Custom vs Built-in     : 0 group(s)
  Custom vs Custom       : 0 group(s)
  Result                 : No duplicate OpType conflicts found.
</code></pre></div></li></ul></article></div>`,1)])])}const _=e(c,[["render",s]]);export{v as __pageData,_ as default};
